"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4661],{3722(e){e.exports=JSON.parse('{"title":"\uc6f9\uc740 \ud45c\uc900 API\ub97c \uafc8\uafb8\uc9c0\ub9cc, \uadf8 \ub0b4\ub9c9\uc740 \ubaa8\ub450 \ub2e4\ub974\ub2e4","date":"2026-01-21","coverUrl":"/kudzu-based-bench/assets/notion/b6c1824acfff9212.png","html":"<h1 data-notion-block-id=\\"2e9e548d-8a8e-80a7-b3d6-dd90b673d5c3\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2ede548d-8a8e-8037-acca-caada7ba0920\\" id=\\"2ede548d-8a8e-8037-acca-caada7ba0920\\">\uc6f9\uc740 \ud45c\uc900 API\ub97c \uafc8\uafb8\uc9c0\ub9cc, \uadf8 \ub0b4\ub9c9\uc740 \ubaa8\ub450 \ub2e4\ub974\ub2e4</h2><a href=\\"https://polypane.app/blog/not-all-browser-apis-are-web-apis/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://polypane.app/blog/not-all-browser-apis-are-web-apis/</a><p data-notion-block-id=\\"2ede548d-8a8e-8020-bf50-e45cf56ef664\\">\uc6f9\uc5d0\uc11c Baseline\uac19\uc740 \ud569\uc758\uccb4\ub85c \ud45c\uc900 API\ub97c \ub9cc\ub4e4\uace0 \ube0c\ub77c\uc6b0\uc800\ub4e4\uc774 \uadf8\uc5d0 \ub9de\uac8c, \uadf8\ub9ac\uace0 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ub97c \uc704\ud574 \ub2e4 \uac19\uc774 \uad6c\ud604\ud558\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c\ud558\uc9c0\ub9cc, \uc774 \uc911 \uc5ec\ub7ec API\ub4e4\uc740 \uadf8\ub807\uc9c0 \ubabb\ud55c \uac83\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc6f9 API\uac00 \ub2e8\uc21c\ud788 Web \uc0cc\ub4dc\ubc15\uc2a4 \uc548\uc5d0\uc11c\ub9cc \ub3cc\uc544\uac00\ub294 API\uac00 \uc544\ub2d8\uc744 \uc54c\uace0 \uad6c\ud604\ud558\ub294\ub370\uc5d0 \uc368\uc57c \ud560 \uac83\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e9e548d-8a8e-80e7-a16b-f6e7062901ef\\" id=\\"2e9e548d-8a8e-80e7-a16b-f6e7062901ef\\">Generator\ub85c Queue\uc2dc\uc2a4\ud15c \ub9cc\ub4e4\uae30</h2><a href=\\"https://macarthur.me/posts/queue/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://macarthur.me/posts/queue/</a><p data-notion-block-id=\\"2e9e548d-8a8e-8040-bbe5-f845459324d1\\"><code>function*</code>\uc73c\ub85c \uc2dc\uc791\ud558\ub294 generator\ub85c \uac12\uc774 \uc5c6\uc73c\uba74 \uc77c\uc2dc\uc911\uc9c0\ud558\uace0, \uac12\uc774 \uc788\ub2e4\uba74 \uc2e4\ud589\ud558\ub294 \ud050\ub97c \ub9cc\ub4e4\uace0, \ud604\uc7ac React \uc0dd\ud0dc\uacc4\uc5d0\uc11c \uc5b4\ub514\uc5d0 \uc4f0\uc77c \uc218 \uc788\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/211e548d-8a8e-8076-80cd-cabfc20df523#212e548d-8a8e-8093-9b0a-f09a93463cf7\\">useSyncExternalStore</a>\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\ub610\ud55c \ud3ec\ud568\ub418\ubbc0\ub85c, UI \ub85c\uc9c1\uc5d0 Queue\uac00 \ud544\uc694\ud558\ub2e4\uba74 \uc608\uc81c \ucf54\ub4dc\ub97c \uc0ac\uc6a9\ud574\ubd10\ub3c4 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2ede548d-8a8e-8009-915d-eca6869c8c22\\" id=\\"2ede548d-8a8e-8009-915d-eca6869c8c22\\">Bun\uc740 \ube60\ub974\ub2e4. \ud558\uc9c0\ub9cc Next.js\uc640 \ud568\uaed8\ub77c\uba74 \ub2e4\ub974\ub2e4</h2><a href=\\"https://blog.platformatic.dev/bun-is-fast-until-latency-matters-for-nextjs-workloads\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.platformatic.dev/bun-is-fast-until-latency-matters-for-nextjs-workloads</a><p data-notion-block-id=\\"2ede548d-8a8e-8052-8906-e987275000c4\\">\uadf8\ub3d9\uc548 Bun\uc774 \ube60\ub974\ub2e4\ub294 \ubca4\uce58\ub9c8\ud06c\ub294 \ub9ce\uc774 \uc788\uc5c8\uc9c0\ub9cc \uc774 \uae00\uc740 \ub2e4\ub985\ub2c8\ub2e4. Node, Watt(Node.js\uc704\uc5d0\uc11c \ub3cc\uc544\uac00\ub294 \uc194\ub8e8\uc158), Deno, Bun\uc73c\ub85c \ubca4\uce58\ub9c8\ud06c \ud14c\uc2a4\ud2b8\ub97c \uc9c4\ud589\ud588\uc744 \uacbd\uc6b0 Bun\uc774 Next.js\uc5d0 \ubd80\ud558\uac00 \uac78\ub838\uc744 \uacbd\uc6b0 \uc9c0\uc5f0 \uc2dc\uac04\uc774 \uac00\uc7a5 \ub290\ub9ac\ub2e4\ub294 \uc0c8\ub85c\uc6b4 \ubca4\uce58\ub9c8\ud06c\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. \uc774 \uae00\uc758 \uacb0\ub860\uacfc \uac19\uc774, \ud2b9\uc131\uc5d0 \ub9de\uac8c \ub7f0\ud0c0\uc784\uc744 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc62c\ubc14\ub974\ub2e4\ub294 \uac83\uc744 \ub9ce\uc740 \ubca4\uce58\ub9c8\ud06c\ub4e4\uc774 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2ede548d-8a8e-8094-a704-d176155a966b\\" id=\\"2ede548d-8a8e-8094-a704-d176155a966b\\">require(esm)\uc774 \ud45c\uc900\uc774 \ub418\uc5b4\uac04\ub2e4</h2><a href=\\"https://joyeecheung.github.io/blog/2025/12/30/require-esm-in-node-js-from-experiment-to-stability/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://joyeecheung.github.io/blog/2025/12/30/require-esm-in-node-js-from-experiment-to-stability/</a><p data-notion-block-id=\\"2ede548d-8a8e-8055-8296-cee6d75cf044\\">Node.js\uc5d0\uc11c \uc65c require(esm)\ubc29\uc2dd\uc774 \ud544\uc694\ud588\ub294\uc9c0, \uc5b4\ub5a4 \uc81c\uc57d\uc0ac\ud56d\uc774 \uc788\uace0 \ud604\uc7ac\ub294 require(esm)\uc774 \uc5b4\ub5bb\uac8c \ub418\uc5c8\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ubc30\ud3ec\ud558\uace0\uc790 \ud558\uba74 \uc774 \uae00\uc744 \uc77d\uace0 \uc9c0\uc6d0\ud558\ub824\ub294 node \ubc84\uc804\uc5d0 \ub530\ub77c ESM\ub9cc \uc9c0\uc6d0\ud558\ub294 \ubc29\ubc95\uc744 \uace0\ub824\ud574\ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \uc120\ud0dd\uc785\ub2c8\ub2e4. \uadf8\ub9ac\uace0 require(esm)\uc744 \uc5b4\ub5bb\uac8c \uad6c\ud604\ud558\ub824\uace0 \uc560\uc37c\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\ub3c4 \uc788\uc73c\ub2c8 \uad00\uc2ec\uc788\uc73c\uba74 \uae00\uc758 \ub9c8\uc9c0\ub9c9 \ub9c1\ud06c\ub97c \ucc38\uc870\ud558\uc2dc\uba74 \uc88b\uc744 \uac83 \uac19\ub124\uc694! \ucd94\uac00\ub85c nodejs \uacf5\uc2dd\uc5d0\uc11c \uc54c\ub824\uc8fc\ub294 <a href=\\"https://nodejs.github.io/package-examples/\\">\ud328\ud0a4\uc9c0 \ubc30\ud3ec \uad00\ub9ac\ubc95</a>\uc744 \uac04\ub2e8\ud788 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2e9e548d-8a8e-801e-a265-c68b0edc7d23\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2ede548d-8a8e-801c-806d-c716145aa258\\" id=\\"2ede548d-8a8e-801c-806d-c716145aa258\\">\uc6f9\uc758 \ud328\ud0a4\uc9c0 \uc885\uc18d\uc131\uc758 \ubb38\uc81c\ub294 \uc5b4\ub514\uc5d0\uc11c \uc654\uc744\uae4c?</h2><a href=\\"https://lea.verou.me/blog/2026/web-deps/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lea.verou.me/blog/2026/web-deps/</a><p data-notion-block-id=\\"2ede548d-8a8e-80e6-87ef-d719333dddb2\\">\ud328\ud0a4\uc9c0 \uc885\uc18d\uc131 \uad00\ub9ac\uac00 \uc65c \ubb38\uc81c\uc778\uc9c0, \ubc88\ub4e4\ub7ec \uc5c6\uc774\ub294 \uc5b4\ub5a4 \ubb38\uc81c\ub4e4\uc774 \uc788\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\uace0, \uc65c \uc218\ub9ce\uc740 \uc124\uc815\ub4e4\uc774 \ud604\ub300 \uc6f9\uc5d0 \ud544\uc694\ud55c\uc9c0 \uc5ec\ub7ec \ubc29\ubc95\ub4e4\uc744 \ud6d1\uc5b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e9e548d-8a8e-8030-880f-c12583113154\\" id=\\"2e9e548d-8a8e-8030-880f-c12583113154\\">\uc704\uc9c0\uc705 \uc5d0\ub514\ud130\uc640 \ubbf8\ub9ac\ubcf4\uae30 \ub80c\ub354\ub9c1 \uc774\uc288</h2><a href=\\"https://handlewithcare.dev/blog/transition_low_priority_editor_updates/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://handlewithcare.dev/blog/transition_low_priority_editor_updates/</a><p data-notion-block-id=\\"2e9e548d-8a8e-8017-acc5-f7ce1159704b\\">\uc704\uc9c0\uc705 \uc5d0\ub514\ud130\ub97c \uc218\uc815\ud558\uba74\uc11c \ubbf8\ub9ac\ubcf4\uae30\ub97c \ub3d9\uc2dc\uc5d0 \ubcf4\uc5ec\uc8fc\uba74 \uc5b4\ub5a4 \uc774\uc288\uac00 \uc788\uc744 \uc218 \uc788\ub294\uc9c0 \ub370\ubaa8\uc640 \ud568\uaed8 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ud574\uacb0\ucc45\uacfc \ud574\uacb0\ucc45\uc758 \uc704\ud5d8\uc131\uae4c\uc9c0\uc694.</p><h2 data-notion-block-id=\\"2ede548d-8a8e-807e-b12c-fd72b09d2186\\" id=\\"2ede548d-8a8e-807e-b12c-fd72b09d2186\\">\ub9ac\uc561\ud2b8\ub97c 10\ub144\ub3d9\uc548 \ub2e4\ub8e8\uba74\uc11c \ucc59\uae34 \uc88b\uc740 \uc608\uc81c\ub97c Agent Skills\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4</h2><a href=\\"https://vercel.com/blog/introducing-react-best-practices\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/introducing-react-best-practices</a><p data-notion-block-id=\\"2ede548d-8a8e-80d6-ba35-c2a02e60fa6b\\">vercel\uc5d0\uc11c 10\ub144\ub3d9\uc548 React\uc640 Next.js\ub97c \ub2e4\ub8e8\uba74\uc11c \ub9cc\ub09c \ucd5c\uc801\ud654 \ud301\uc744 \ubaa8\uc740 Agent Skills\ub85c \ub9cc\ub4e4\uc5b4\uc11c \ubcfc \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ud569\ub2c8\ub2e4. Agent\ub97c \uc0ac\uc6a9\ud558\uace0 \uc788\ub2e4\uba74 \uc0ac\uc6a9\ud574\ubcf4\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc544\ubcf4\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"2e9e548d-8a8e-80d1-8c87-fa9ca5eafbfb\\" id=\\"2e9e548d-8a8e-80d1-8c87-fa9ca5eafbfb\\">RSC\uc5d0\uc11c Client Component\ub85c \uac12\uc744 \uc5b4\ub5bb\uac8c \uc804\ub2ec\ud558\ub294\uac00</h2><a href=\\"https://next-16-recipes.vercel.app/sharing-data-with-client-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://next-16-recipes.vercel.app/sharing-data-with-client-components</a><h2 data-notion-block-id=\\"2e9e548d-8a8e-80e8-9099-fd115f353530\\" id=\\"2e9e548d-8a8e-80e8-9099-fd115f353530\\">Node.js \uc548\uc5d0\uc11c Queue\uc791\uc5c5\uc744 \ud558\ub824\uba74 \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc88b\uc744\uae4c?</h2><a href=\\"https://judoscale.com/blog/node-task-queues\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://judoscale.com/blog/node-task-queues</a><h2 data-notion-block-id=\\"2e9e548d-8a8e-809a-8250-db78ed831bc2\\" id=\\"2e9e548d-8a8e-809a-8250-db78ed831bc2\\">\ub85c\uadf8\ub294 \uc5b4\ub5bb\uac8c \uad6c\uc131\ub418\uc5b4\uc57c \ud558\ub294\uac00</h2><a href=\\"https://loggingsucks.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://loggingsucks.com/</a><p data-notion-block-id=\\"2e9e548d-8a8e-805e-b1fd-da5ccb3a0976\\">\ub85c\uae45 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub9cc \ubd99\uc774\uba74 \ub514\ubc84\uae45\uc774 \uc26c\uc6cc\uc9c0\ub294 \uac83\uc774 \uc544\ub2d8\uc744, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ub85c\uae45\uc744 \ubc14\uafd4\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uc778\ud130\ub809\ud2f0\ube0c\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e9e548d-8a8e-8092-a1b9-e02f1d8d535e\\" id=\\"2e9e548d-8a8e-8092-a1b9-e02f1d8d535e\\">2025\ub144 React Native \ub9ac\ubdf0</h2><a href=\\"https://www.callstack.com/blog/react-native-wrapped-2025-a-month-by-month-recap-of-the-year\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/react-native-wrapped-2025-a-month-by-month-recap-of-the-year</a><a href=\\"https://shift.infinite.red/react-native-wrapped-2025-the-year-we-entered-our-polishing-era-79c6a3e5b4b7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shift.infinite.red/react-native-wrapped-2025-the-year-we-entered-our-polishing-era-79c6a3e5b4b7</a><p data-notion-block-id=\\"2e9e548d-8a8e-806f-b2fe-e23160bdce76\\">React Native\uc5d0 \uc5b4\ub5a4 \uc77c\uc774 \uc788\uc5c8\ub294\uc9c0 \uac04\ub2e8\ud558\uac8c \ubcf4\uae30 \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e9e548d-8a8e-8051-80ec-d921adc5f304\\" id=\\"2e9e548d-8a8e-8051-80ec-d921adc5f304\\">\uc88b\uc740 \ud14c\uc2a4\ud2b8\ub97c \uc4f0\uae30 \uc704\ud55c \uccb4\ud06c\ub9ac\uc2a4\ud2b8</h2><a href=\\"https://howtotestfrontend.com/resources/how-to-write-good-frontend-tests\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://howtotestfrontend.com/resources/how-to-write-good-frontend-tests</a><h1 data-notion-block-id=\\"2e9e548d-8a8e-80d4-96c9-fa072e457da7\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://astro.build/blog/astro-6-beta/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-6-beta/</a><p data-notion-block-id=\\"2e9e548d-8a8e-8041-87a4-d0019a1c052f\\">Live Collection \uae30\ub2a5\uacfc CSP \uc124\uc815 \uc548\uc815\ud654 \uae30\ub2a5\uc774 \ud3ec\ud568\ub41c Astro 6 \ubca0\ud0c0 \ubc84\uc804\uc774 \ub098\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.callstack.com/blog/live-activities-and-widgets-with-react-say-hello-to-voltra\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/live-activities-and-widgets-with-react-say-hello-to-voltra</a><p data-notion-block-id=\\"2e9e548d-8a8e-8078-95b2-cc1b81f02b08\\">React Native\uc5d0\uc11c iOS Widget\uc744 \uc27d\uac8c \uad6c\ud604\ud560 \uc218 \uc788\uac8c \ub3c4\uc640\uc8fc\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.rnsec.dev/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.rnsec.dev/</a><p data-notion-block-id=\\"2e9e548d-8a8e-80c6-a733-e3593d73187c\\">React Native\uc571\uc5d0\uc11c \uc5b4\ub5a4 \ubcf4\uc548 \uc704\ud611\uc774 \uc788\ub294\uc9c0 \uc54c\ub824\uc8fc\ub294 \uc624\ud508\uc18c\uc2a4 \ud234\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e9e548d-8a8e-808a-bf09-c392239732ed\\" id=\\"2e9e548d-8a8e-808a-bf09-c392239732ed\\">\ubc88\uc678: GC\uc640 \uacf5\ubcc0\uc131\uacfc \ubc18\uacf5\ubcc0\uc131</h2><a href=\\"https://trynova.dev/blog/garbage-collection-is-contrarian\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://trynova.dev/blog/garbage-collection-is-contrarian</a><p data-notion-block-id=\\"2ede548d-8a8e-80e1-89e2-dde68ae580ec\\">Rust \uae30\ubc18 \uae00\uc774\uc5ec\uc11c \uc77d\uae30\uac00 \ud798\ub4e0 \uae00\uc774\uc9c0\ub9cc, \uacf5\ubcc0\uc131\uacfc \ubc18\uacf5\ubcc0\uc131\uc774 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 GC\ub294 \uc65c \ubc18\uacf5\ubcc0\uc801\uc774\uc5ec\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);